296#NK:	//    - calls `cli.mjs start` to record the started event;
297#KB:	//    - traps EXIT to call `cli.mjs done <code>` (or `cancelled` if a .cancelled flag is present);
298#BR:	//    - also writes the @pi-exit-code pane option for the readPaneExitCode fallback.
299#ZW:	const script = [
300#TN:		"#!/bin/bash",
301#WZ:		"set -e",
302#RY:		`export ARTIFACT_DIR=${shellEscape(artifactDir)}`,
303#TW:		`"${cliPath}" start`,
304#ZM:		`trap 'if [ -f "${artifactDir}/.cancelled" ]; then "${cliPath}" cancelled; else "${cliPath}" done "$?"; fi; tmux set-option -p -t "$TMUX_PANE" @pi-exit-code "$?" 2>/dev/null || true' EXIT`,
