 83#QW: * Read all events for a sub-agent. If `since` is provided, only events with
 84#XJ: * ts >= since are returned. Malformed lines are silently skipped (the
 85#TK: * sub-agent CLI is the only writer, but a partial write could in theory
 86#YZ: * leave a truncated line).
 87#WM: *
 88#TY: * Uses the `ndjson` library with `strict: false` so a single bad line does not abort the whole
 89#ZB: * file — ndjson drops the bad row and continues with the rest. Any trailing partial line (file
 90#ZB: * did not end with a newline) is buffered by the parser and dropped on `end()`; it is treated as a
 91#KR: * in-progress write that the next reader will pick up once completed.
 92#VQ: */
 93#JK:export function readEvents(art: SubagentArtifact, since?: number): SubagentEvent[] {
 94#NZ:	if (!existsSync(art.statusFile)) return [];
 95#MR:	let content: string;
 96#TZ:	try {
 97#VJ:		content = readFileSync(art.statusFile, "utf8");
