 99#RT:		return [];
100#HP:	}
101#RY:	const parser = ndjson.parse({ strict: false });
102#JX:	const events: SubagentEvent[] = [];
103#YZ:	parser.on("data", (obj: unknown) => {
104#JH:		const ev = obj as SubagentEvent;
105#VV:		if (since === undefined || ev.ts >= since) events.push(ev);
106#BZ:	});
107#BM:	// Non-strict mode never emits 'error' for bad JSON; attach a no-op so an unhandled error event
108#RV:	// can never crash the parent process.
109#NQ:	parser.on("error", () => {});
110#XQ:	parser.end(Buffer.from(content, "utf8"));
111#TW:	return events;
112#HR:}
